  const delays = [];
  let attempts = 0;
  const fn = async () => {
    attempts++;
    if (attempts <= failFirst) throw new Error("fail " + attempts);
    return "ok";
  };
  const sleep = async (ms) => {
    delays.push(ms);
  };
  try {
    return { result: await retryWithBackoff(fn, retries, baseMs, sleep), delays, attempts };
  } catch (e) {
    return { result: "error: " + e.message, delays, attempts };
  }
}

