function createLoader(fetchMany) {
  return async (key) => {
    const [value] = await fetchMany([key]);
    return value;
  };
}

// Test driver (leave as is): each group of keys is loaded together; groups run one after another.
// fetchMany fails for any batch containing "boom".
async function runLoader(groups) {
  const batches = [];
  const load = createLoader(async (keys) => {
    batches.push(keys);
    await null;
    if (keys.includes("boom")) throw new Error("batch failed");
    return keys.map((k) => k.toUpperCase());
  });
  const values = [];
  for (const group of groups) {
    values.push(await Promise.all(group.map((k) => load(k).catch((e) => "error: " + e.message))));
  }
  return { values, batches };
}

