function createLoader(fetchMany) {
  let queue = [];
  return (key) =>
    new Promise((resolve, reject) => {
      queue.push({ key, resolve, reject });
      if (queue.length === 1) {
        Promise.resolve().then(async () => {
          const batch = queue;
          queue = [];
          try {
            const values = await fetchMany(batch.map((b) => b.key));
            batch.forEach((b, i) => b.resolve(values[i]));
          } catch (e) {
            batch.forEach((b) => b.reject(e));
          }
        });
      }
    });
}

