  if (abortAt === 0) abort();
  else if (abortAt > 0) ticks(abortAt).then(abort);
  let started = false;
  const task = async () => {
    started = true;
    await ticks(taskTicks);
    return "done";
  };
  try {
    return { result: await withSignal(task, signal), started };
  } catch (e) {
    return { result: "error: " + (e as Error).message, started };
  }
